      document.getElementById('enableWatchedElementGate').checked = s.enableWatchedElementGate === true;
      document.getElementById('watchedElementSelector').value = s.watchedElementSelector || '';
      document.getElementById('enableStopWord').checked = s.enableStopWord === true;
      document.getElementById('stopWord').value = s.stopWord || '';
      document.getElementById('stopWordCaseSensitive').checked = s.stopWordCaseSensitive === true;
      document.getElementById('refreshTabBeforeEachPrompt').checked = s.refreshTabBeforeEachPrompt === true;
      document.getElementById('parallelOneTabPerPrompt').checked = s.parallelOneTabPerPrompt === true;
      document.getElementById('parallelActivateTabBeforeSend').checked = s.parallelActivateTabBeforeSend === true;
      document.getElementById('openNewChatPerPrompt').checked = s.openNewChatPerPrompt === true;
      document.getElementById('openNewChatPerPromptUrl').value = s.openNewChatPerPromptUrl || '';

      const stopWordContainer = document.getElementById('stopWordContainer');
      const watchedElementContainer = document.getElementById('watchedElementContainer');
      if (s.enableStopWord === true) {
        stopWordContainer.classList.remove('hidden');
      } else {
        stopWordContainer.classList.add('hidden');
      }
      if (s.enableWatchedElementGate === true) {
        watchedElementContainer.classList.remove('hidden');
      } else {
        watchedElementContainer.classList.add('hidden');
      }
    }
  } catch (e) {
    console.error('[LoadSettings] Error:', e);
  }
}

export async function saveSettingsFromUI() {
  let settings = null;
  try {
    const maxWaitSec = Number(document.getElementById('maxWaitSec').value);
    const stableMinSec = Number(document.getElementById('stableMinSec').value);
    const stableMaxSec = Number(document.getElementById('stableMaxSec').value);
    const stableMinOrdered = Math.min(stableMinSec, stableMaxSec || stableMinSec);
    const stableMaxOrdered = Math.max(stableMinSec || stableMaxSec, stableMaxSec || stableMinSec);
    const pollSec = Number(document.getElementById('pollSec').value);
    settings = {
      maxWaitMs: secToMs(maxWaitSec),
      stableMinMs: secToMs(stableMinOrdered),
      stableMaxMs: secToMs(stableMaxOrdered),
      pollIntervalMs: secToMs(pollSec),
      enableRetryOnFailure: document.getElementById('enableRetryOnFailure').checked,
      maxRetriesPerPrompt: Number(document.getElementById('maxRetriesPerPrompt').value),
      retryDelayMs: secToMs(Number(document.getElementById('retryDelaySec').value)),
      systemPrompt: document.getElementById('systemPrompt').value || '',
      appendPromptText: document.getElementById('appendPromptText').value || '',
      prependSystemPrompt: document.getElementById('prependSystemPrompt').checked,
      appendSystemPrompt: document.getElementById('appendSystemPrompt').checked,
      enableMaxWaitTimeout: document.getElementById('enableMaxWaitTimeout').checked,
      autoConfirmDialogs: document.getElementById('autoConfirmDialogs').checked,
      enableWatchedElementGate: document.getElementById('enableWatchedElementGate').checked,
      watchedElementSelector: (document.getElementById('watchedElementSelector').value || '').trim(),
      enableStopWord: document.getElementById('enableStopWord').checked,
      stopWord: document.getElementById('stopWord').value || '',
      stopWordCaseSensitive: document.getElementById('stopWordCaseSensitive').checked,
      refreshTabBeforeEachPrompt: document.getElementById('refreshTabBeforeEachPrompt').checked,
      parallelOneTabPerPrompt: document.getElementById('parallelOneTabPerPrompt').checked,
      parallelActivateTabBeforeSend: document.getElementById('parallelActivateTabBeforeSend').checked,
      openNewChatPerPrompt: document.getElementById('openNewChatPerPrompt').checked,
      openNewChatPerPromptUrl: (document.getElementById('openNewChatPerPromptUrl').value || '').trim(),
    };
    await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings });
    return settings;
  } catch (e) {
    console.error('[SaveSettings] Error:', e);
    return settings;
  }
}

export function initSettingsUI() {
  applyConsolePatch();

  const themeSelect = document.getElementById('themeSelect');
  if (themeSelect) {
    themeSelect.addEventListener('change', async (e) => {
      const val = e.target.value;
      applyTheme(val);
      try {
        await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings: { theme: val } });
      } catch (err) {
        console.error('[ThemeChange] Error:', err);
      }
    });
  }

  ['maxWaitSec', 'stableMinSec', 'stableMaxSec', 'pollSec', 'enableRetryOnFailure', 'maxRetriesPerPrompt', 'retryDelaySec', 'systemPrompt', 'appendPromptText', 'prependSystemPrompt', 'appendSystemPrompt', 'enableMaxWaitTimeout', 'autoConfirmDialogs', 'enableWatchedElementGate', 'watchedElementSelector', 'refreshTabBeforeEachPrompt', 'parallelOneTabPerPrompt', 'parallelActivateTabBeforeSend'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', saveSettingsFromUI);
  });

  const enableMaxWaitTimeoutCheckbox = document.getElementById('enableMaxWaitTimeout');
  if (enableMaxWaitTimeoutCheckbox) {
    enableMaxWaitTimeoutCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  const enableStopWordCheckbox = document.getElementById('enableStopWord');
  const stopWordContainer = document.getElementById('stopWordContainer');
  const stopWordInput = document.getElementById('stopWord');
  const stopWordCaseSensitiveCheckbox = document.getElementById('stopWordCaseSensitive');
  const enableWatchedElementGateCheckbox = document.getElementById('enableWatchedElementGate');
  const watchedElementContainer = document.getElementById('watchedElementContainer');
  const watchedElementSelectorInput = document.getElementById('watchedElementSelector');
  const useChatgptActionSelectorBtn = document.getElementById('useChatgptActionSelector');
  const openNewChatPerPromptCheckbox = document.getElementById('openNewChatPerPrompt');
  const openNewChatPerPromptUrlInput = document.getElementById('openNewChatPerPromptUrl');

  if (enableStopWordCheckbox) {
    enableStopWordCheckbox.addEventListener('change', () => {
      if (enableStopWordCheckbox.checked) {
        stopWordContainer.classList.remove('hidden');
        stopWordInput.focus();
      } else {
        stopWordContainer.classList.add('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (stopWordInput) {
    stopWordInput.addEventListener('input', saveSettingsFromUI);
  }

  if (stopWordCaseSensitiveCheckbox) {
    stopWordCaseSensitiveCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  if (enableWatchedElementGateCheckbox) {
    enableWatchedElementGateCheckbox.addEventListener('change', () => {
      if (enableWatchedElementGateCheckbox.checked) {
        watchedElementContainer.classList.remove('hidden');
        watchedElementSelectorInput.focus();
      } else {
        watchedElementContainer.classList.add('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (watchedElementSelectorInput) {
    watchedElementSelectorInput.addEventListener('input', saveSettingsFromUI);
  }

  if (useChatgptActionSelectorBtn) {
    useChatgptActionSelectorBtn.addEventListener('click', () => {
      watchedElementSelectorInput.value = 'button[data-testid="copy-turn-action-button"]';
      if (enableWatchedElementGateCheckbox && !enableWatchedElementGateCheckbox.checked) {
        enableWatchedElementGateCheckbox.checked = true;
        watchedElementContainer.classList.remove('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (openNewChatPerPromptCheckbox) {
    openNewChatPerPromptCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  if (openNewChatPerPromptUrlInput) {
    openNewChatPerPromptUrlInput.addEventListener('change', saveSettingsFromUI);
    openNewChatPerPromptUrlInput.addEventListener('blur', saveSettingsFromUI);
  }
}

import { applyConsolePatch } from './popup-console-patch.js';
import { setStatus, setProgress, showToast, showError, hideError, clearError, setButtonsDisabled, secToMs } from './popup-dom-utils.js';
import { loadSettingsIntoUI, saveSettingsFromUI, initSettingsUI } from './popup-settings.js';
import { loadHistoryIntoUI, importHistoryItems, clearHistory, exportHistory, saveHistoryItem } from './popup-history.js';
import { NEW_TAB_MARKER, resolveSeparator, buildPromptLaunchPlan } from './popup-prompt-plan.js';

applyConsolePatch();

const separatorInput = document.getElementById('separatorInput');

async function getActiveTabId() {
  const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
  return tabs?.[0]?.id;
}

const pauseBtn = document.getElementById('pauseBtn');
const resumeBtn = document.getElementById('resumeBtn');
const parallelWalkthrough = document.getElementById('parallelWalkthrough');
const toggleParallelWalkthroughBtn = document.getElementById('toggleParallelWalkthroughBtn');
const PARALLEL_WALKTHROUGH_VISIBILITY_KEY = 'parallelWalkthroughVisible';
const POPUP_ACTIVE_VIEW_KEY = 'popupActiveView';
const DEFAULT_POPUP_VIEW = 'serial';
const viewTabs = Array.from(document.querySelectorAll('.view-tab[data-view-target]'));
const viewPanels = Array.from(document.querySelectorAll('.view-panel[data-views]'));
const helpIcons = Array.from(document.querySelectorAll('.help-icon[data-help]'));
let helpTooltipEl = null;
let activeHelpIcon = null;
let helpHideTimer = null;

function parseViewList(panel) {
  const raw = panel?.dataset?.views || '';
  return raw
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

function setActiveView(viewName) {
  const normalizedView = typeof viewName === 'string' && viewName.trim() ? viewName.trim() : DEFAULT_POPUP_VIEW;
  viewTabs.forEach((tab) => {
    const active = tab.dataset.viewTarget === normalizedView;
    tab.classList.toggle('active', active);
    tab.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  viewPanels.forEach((panel) => {
    const visible = parseViewList(panel).includes(normalizedView);
    panel.hidden = !visible;
  });
}

async function loadActiveView() {
  let nextView = DEFAULT_POPUP_VIEW;
  try {
    const result = await chrome.storage.local.get([POPUP_ACTIVE_VIEW_KEY]);
    const storedView = result?.[POPUP_ACTIVE_VIEW_KEY];
    if (typeof storedView === 'string' && storedView.trim()) {
      nextView = storedView.trim();
    }
  } catch (e) {
    console.error('[PopupView] Failed to load active view:', e);
  }
  setActiveView(nextView);
}

viewTabs.forEach((tab) => {
  tab.addEventListener('click', async () => {
    const target = tab.dataset.viewTarget || DEFAULT_POPUP_VIEW;
    setActiveView(target);
    try {
      await chrome.storage.local.set({ [POPUP_ACTIVE_VIEW_KEY]: target });
    } catch (e) {
      console.error('[PopupView] Failed to save active view:', e);
    }
  });
});

function ensureHelpTooltip() {
  if (helpTooltipEl) return helpTooltipEl;
  helpTooltipEl = document.createElement('div');
  helpTooltipEl.className = 'help-tooltip';
  helpTooltipEl.hidden = true;
  document.body.appendChild(helpTooltipEl);
  return helpTooltipEl;
}

function positionHelpTooltip(iconEl) {
  if (!helpTooltipEl || !iconEl) return;
  const iconRect = iconEl.getBoundingClientRect();
  const tooltipRect = helpTooltipEl.getBoundingClientRect();
  const gap = 8;
  const maxLeft = Math.max(8, window.innerWidth - tooltipRect.width - 8);
  const preferredLeft = Math.min(maxLeft, Math.max(8, iconRect.left + (iconRect.width / 2) - (tooltipRect.width / 2)));
  let top = iconRect.bottom + gap;
  if (top + tooltipRect.height > window.innerHeight - 8) {
    top = Math.max(8, iconRect.top - tooltipRect.height - gap);
  }
  helpTooltipEl.style.left = `${preferredLeft}px`;
  helpTooltipEl.style.top = `${top}px`;
}

function hideHelpTooltip(immediate = false) {
  if (!helpTooltipEl) return;
  if (helpHideTimer) {
    clearTimeout(helpHideTimer);
    helpHideTimer = null;
  }
  const doHide = () => {
    helpTooltipEl.classList.remove('visible');
    helpTooltipEl.hidden = true;
    activeHelpIcon = null;
  };
  if (immediate) {
    doHide();
    return;
  }
  helpHideTimer = setTimeout(doHide, 80);
}

function showHelpTooltip(iconEl) {
  if (!iconEl) return;
  const tooltip = ensureHelpTooltip();
  if (helpHideTimer) {
    clearTimeout(helpHideTimer);
    helpHideTimer = null;
  }
  tooltip.textContent = iconEl.dataset.help || '';
  tooltip.hidden = false;
  tooltip.classList.add('visible');
  activeHelpIcon = iconEl;
  positionHelpTooltip(iconEl);
}

function bindHelpTooltipEvents() {
  if (!helpIcons.length) return;

  helpIcons.forEach((icon) => {
    icon.addEventListener('mouseenter', () => showHelpTooltip(icon));
    icon.addEventListener('focus', () => showHelpTooltip(icon));
    icon.addEventListener('mouseleave', () => hideHelpTooltip());
    icon.addEventListener('blur', () => hideHelpTooltip());
    icon.addEventListener('click', (e) => {
      e.preventDefault();
      if (activeHelpIcon === icon && helpTooltipEl && !helpTooltipEl.hidden) {
        hideHelpTooltip(true);
        return;
      }
      showHelpTooltip(icon);
    });
  });

  document.addEventListener('click', (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest('.help-icon')) return;
    if (target.closest('.help-tooltip')) return;
    hideHelpTooltip(true);
  });

  window.addEventListener('resize', () => {
    if (!activeHelpIcon || !helpTooltipEl || helpTooltipEl.hidden) return;
    positionHelpTooltip(activeHelpIcon);
  });
}

function setParallelWalkthroughVisibility(visible) {
  if (!parallelWalkthrough || !toggleParallelWalkthroughBtn) return;
  parallelWalkthrough.hidden = !visible;
  toggleParallelWalkthroughBtn.textContent = visible ? 'Hide guide' : 'Show guide';
}

async function loadParallelWalkthroughVisibility() {
  if (!parallelWalkthrough || !toggleParallelWalkthroughBtn) return;
  let visible = true;
  try {
    const result = await chrome.storage.local.get([PARALLEL_WALKTHROUGH_VISIBILITY_KEY]);
    if (typeof result?.[PARALLEL_WALKTHROUGH_VISIBILITY_KEY] === 'boolean') {
      visible = result[PARALLEL_WALKTHROUGH_VISIBILITY_KEY];
    }
  } catch (e) {
    console.error('[ParallelWalkthrough] Failed to load visibility:', e);
  }
  setParallelWalkthroughVisibility(visible);
}

if (toggleParallelWalkthroughBtn && parallelWalkthrough) {
  toggleParallelWalkthroughBtn.addEventListener('click', async () => {
    const currentlyVisible = !parallelWalkthrough.hidden;
    const nextVisible = !currentlyVisible;
    setParallelWalkthroughVisibility(nextVisible);
    try {
      await chrome.storage.local.set({ [PARALLEL_WALKTHROUGH_VISIBILITY_KEY]: nextVisible });
    } catch (e) {
      console.error('[ParallelWalkthrough] Failed to save visibility:', e);
    }
  });
}

function updateControlButtons(status = {}) {
  const running = !!status.running;
  const paused = !!status.paused;

  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');

  if (startBtn) startBtn.disabled = running;
  if (stopBtn) stopBtn.disabled = !running;

  if (pauseBtn) {
    pauseBtn.style.display = running && !paused ? 'inline-block' : 'none';
    pauseBtn.disabled = !running || paused;
  }
  if (resumeBtn) {
    resumeBtn.style.display = running && paused ? 'inline-block' : 'none';
    resumeBtn.disabled = !running || !paused;
  }
}

function getRunningStatusText(status = {}) {
  const {
    mode = 'sequential',
    paused,
    currentIndex = 0,
    total = 0,
    recoveryAttempts = 0,
    currentRetryCount = 0,
    options = {},
    parallelLaunched = 0,
    parallelCompleted = 0,
    parallelUncertain = 0,
    parallelFailed = 0,
    parallelActive = 0,
  } = status;

  if (mode === 'parallel') {
    if (paused) {
      return `Paused launches - launched ${parallelLaunched}/${total}, active ${parallelActive}, done ${parallelCompleted}, uncertain ${parallelUncertain}, failed ${parallelFailed}`;
    }
    return `Parallel running - launched ${parallelLaunched}/${total}, active ${parallelActive}, done ${parallelCompleted}, uncertain ${parallelUncertain}, failed ${parallelFailed}`;
  }

  if (paused) {
    return `Paused at prompt ${currentIndex + 1} of ${total}`;
  }
  if (recoveryAttempts > 0) {
    return `Recovering... (attempt ${recoveryAttempts}/3) - Prompt ${currentIndex + 1} of ${total}`;
  }
  if (currentRetryCount > 0) {
    const maxRetries = Number(options?.maxRetriesPerPrompt || 0);
    return `Retrying prompt ${currentIndex + 1} of ${total} (${currentRetryCount}/${maxRetries || '?'})`;
  }
  return `Running prompt ${currentIndex + 1} of ${total}...`;
}

function getProgressPosition(status = {}) {
  if (status.mode === 'parallel') {
    const completed = Number(status.parallelCompleted || 0);
    const failed = Number(status.parallelFailed || 0);
    return completed + failed;
  }
  return Number(status.currentIndex || 0);
}

async function refreshStatus() {
  try {
    const res = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
    if (res?.ok && res.status) {
      const { running, paused, total, currentIndex } = res.status;
      const progressPos = getProgressPosition(res.status);
      setProgress(running ? progressPos : total, total);
      setButtonsDisabled(running && !paused);
      updateControlButtons(res.status);
      if (running) {
        setStatus(getRunningStatusText(res.status), res.status.paused ? 'paused' : 'running');
      } else if (total > 0 && currentIndex >= total) {
        setStatus('Complete', 'idle');
      } else {
        setStatus('Idle', 'idle');
      }
    }
  } catch (e) {
    console.error('[RefreshStatus] Error:', e);
  }
}

initSettingsUI();

async function startAutomation() {
  try {
    // Check if automation is already running
    const statusRes = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
    if (statusRes?.ok && statusRes.status?.running) {
      showToast('Automation is already running. Stop it first.', 'error');
      setStatus(getRunningStatusText(statusRes.status), statusRes.status.paused ? 'paused' : 'running');
      return;
    }

    const textarea = document.getElementById('prompts');
    const separatorInput = document.getElementById('separatorInput');
    const separator = resolveSeparator(separatorInput?.value);
    const launchPlan = buildPromptLaunchPlan(textarea.value, separator);
    const prompts = launchPlan.prompts;
    if (prompts.length === 0) {
      setStatus('Please enter at least one prompt.');
      return;
    }
    if (launchPlan.duplicateChanged > 0) {
      showToast(`Adjusted ${launchPlan.duplicateChanged} duplicate prompt(s) with typo-like variations`, 'info', 4000);
    }
    const tabId = await getActiveTabId();
    if (!tabId) {
      setStatus('No active tab found.');
      return;
    }
    setStatus('Starting...');
    hideError(); // Clear any previous error
    // Get current settings and include them in START_AUTOMATION to avoid race conditions
    const uiSettings = await saveSettingsFromUI();
    let currentSettings = { ...(uiSettings || {}) };
    if (!uiSettings) {
      const settingsRes = await chrome.runtime.sendMessage({ type: 'GET_SETTINGS' });
      currentSettings = { ...(settingsRes?.settings || {}) };
    }
    const appendText = typeof currentSettings.appendPromptText === 'string'
      ? currentSettings.appendPromptText.trim()
      : '';
    if (appendText && currentSettings.appendSystemPrompt !== true) {
      currentSettings.appendSystemPrompt = true;
      showToast('Append text found; auto-enabling append for this run.', 'info', 3000);
    }
    const parallelTabCount = launchPlan.tabPromptGroups.length;
    if (currentSettings.parallelOneTabPerPrompt === true && launchPlan.hasTabMarkers) {
      showToast(`Detected ${parallelTabCount} tab group(s) using ${NEW_TAB_MARKER}`, 'info', 3000);
    }
    const res = await chrome.runtime.sendMessage({
      type: 'START_AUTOMATION',
      prompts,
      tabPromptGroups: launchPlan.tabPromptGroups,
      tabId,
      options: currentSettings,
    });
    if (res?.ok) {
      const initialStatus = currentSettings.parallelOneTabPerPrompt === true
        ? { mode: 'parallel', running: true, paused: false, total: parallelTabCount, parallelLaunched: 0, parallelCompleted: 0, parallelFailed: 0, parallelActive: 0 }
        : { mode: 'sequential', running: true, paused: false, currentIndex: 0, total: prompts.length };
      setStatus(getRunningStatusText(initialStatus), 'running');
      setProgress(getProgressPosition(initialStatus), initialStatus.total);
      updateControlButtons({ running: true, paused: false });
      await chrome.runtime.sendMessage({
        type: 'SAVE_PROMPT_HISTORY',
        item: { prompts: launchPlan.promptsWithMarkers, settings: currentSettings },
      });
    } else {
      setStatus(`Failed to start: ${res?.error || 'Unknown error'}`, 'error');
      showToast(res?.error || 'Failed to start', 'error');
    }
  } catch (e) {
    console.error('[StartAutomation] Error:', e);
    setStatus(`Failed to start: ${e}`, 'error');
  }
}

document.getElementById('startBtn').addEventListener('click', startAutomation);

if (pauseBtn) {
  pauseBtn.addEventListener('click', async () => {
    try {
      const res = await chrome.runtime.sendMessage({ type: 'PAUSE_AUTOMATION' });
      if (res?.ok) {
        setStatus('Paused', 'paused');
        updateControlButtons({ running: true, paused: true });
      } else {
        showToast(res?.error || 'Failed to pause', 'error');
      }
    } catch (e) {
      console.error('[PauseBtn] Error:', e);
      showToast('Failed to pause', 'error');
    }
  });
}

if (resumeBtn) {
  resumeBtn.addEventListener('click', async () => {
    try {
      const res = await chrome.runtime.sendMessage({ type: 'RESUME_AUTOMATION' });
      if (res?.ok) {
        setStatus('Resuming...', 'running');
        updateControlButtons({ running: true, paused: false });
      } else {
        showToast(res?.error || 'Failed to resume', 'error');
      }
    } catch (e) {
      console.error('[ResumeBtn] Error:', e);
      showToast('Failed to resume', 'error');
    }
  });
}

document.getElementById('stopBtn').addEventListener('click', async () => {
  try {
    await chrome.runtime.sendMessage({ type: 'STOP_AUTOMATION' });
    setStatus('Stopped');
    updateControlButtons({ running: false, paused: false });
    // Refresh to clear any recovery status
    await refreshStatus();
  } catch (e) {
    console.error('[StopBtn] Error:', e);
    setStatus('Stop failed');
  }
});

// Save current prompts to history
const saveHistoryBtn = document.getElementById('saveHistoryBtn');
if (saveHistoryBtn) {
  saveHistoryBtn.addEventListener('click', async () => {
    try {
      const textarea = document.getElementById('prompts');
      const separatorInput = document.getElementById('separatorInput');
      const separator = resolveSeparator(separatorInput?.value);
      const launchPlan = buildPromptLaunchPlan(textarea.value, separator);
      const prompts = launchPlan.prompts;
      if (prompts.length === 0) {
        showToast('No prompts to save', 'error');
        return;
      }
      if (launchPlan.duplicateChanged > 0) {
        showToast(`Adjusted ${launchPlan.duplicateChanged} duplicate prompt(s) before save`, 'info', 3500);
      }
      const settings = await chrome.runtime.sendMessage({ type: 'GET_SETTINGS' });
      await saveHistoryItem(launchPlan.promptsWithMarkers, settings?.settings);
      // Immediately refresh the history list
      await loadHistoryIntoUI(updatePromptCount);
      showToast('✓ Saved to history', 'success');
    } catch (e) {
      console.error('[SaveHistoryBtn] Error:', e);
      showToast('Failed to save history', 'error');
    }
  });
}

// Add reload history button listener
const reloadHistoryBtn = document.getElementById('reloadHistoryBtn');
if (reloadHistoryBtn) {
  reloadHistoryBtn.addEventListener('click', async () => {
    try {
      await loadHistoryIntoUI();
      showToast('✓ History reloaded', 'success');
    } catch (e) {
      console.error('[ReloadHistoryBtn] Error:', e);
      showToast('Failed to reload history', 'error');
    }
  });
}

// Export history as JSON
const exportBtn = document.getElementById('exportBtn');
if (exportBtn) {
  exportBtn.addEventListener('click', async () => {
    try {
      const exportData = await exportHistory();
      if (!exportData) return;
      const jsonString = JSON.stringify(exportData, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `prompt-queue-export-${Date.now()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      showToast(`✓ Exported ${exportData.history.length} items`, 'success');
    } catch (e) {
      console.error('[ExportBtn] Error:', e);
      showToast('Export failed', 'error');
    }
  });
}

// Import history from JSON
const importBtn = document.getElementById('importBtn');
const importFile = document.getElementById('importFile');
if (importBtn && importFile) {
  importBtn.addEventListener('click', () => {
    importFile.click();
  });

  importFile.addEventListener('change', async (event) => {
    try {
      const file = event.target.files?.[0];
      if (!file) return;

      const text = await file.text();
      const importData = JSON.parse(text);

      const result = await importHistoryItems(importData);
      await loadHistoryIntoUI(updatePromptCount);

      let message = `✓ Imported ${result.imported} item${result.imported !== 1 ? 's' : ''}`;
      if (result.duplicates > 0) message += ` (${result.duplicates} duplicate${result.duplicates !== 1 ? 's' : ''} skipped)`;
      if (result.invalid > 0) message += ` (${result.invalid} invalid skipped)`;
      showToast(message, result.imported > 0 ? 'success' : 'error');
    } catch (e) {
      console.error('[ImportFile] Error:', e);
      showToast(`Import failed: ${e.message}`, 'error');
    }

    // Reset file input
    importFile.value = '';
  });
}

chrome.runtime.onMessage.addListener((message) => {
  try {
    if (message?.type === 'AUTOMATION_PROGRESS' && message.status) {
      const { total, paused, running } = message.status;
      lastActivityTime = Date.now();
      setButtonsDisabled(running && !paused);
      clearError();
      updateControlButtons(message.status);
      setStatus(getRunningStatusText(message.status), paused ? 'paused' : 'running');
      setProgress(getProgressPosition(message.status), total);
    } else if (message?.type === 'AUTOMATION_COMPLETE') {
      const reason = message.reason;
      const status = message.status;
      const lastFailureError = status?.parallelLastFailure?.error;
      if (reason === 'stoppedByStopWord') {
        setStatus('Stopped by stop phrase', 'idle');
      } else if (reason === 'completedWithErrors') {
        setStatus(lastFailureError ? `Complete with errors: ${lastFailureError}` : 'Complete with errors', 'error');
      } else {
        setStatus('Complete', 'idle');
      }
      if (status?.total && typeof status.currentIndex === 'number') {
        const progressPos = status.mode === 'parallel'
          ? Number(status.parallelCompleted || 0) + Number(status.parallelFailed || 0)
          : status.currentIndex;
        setProgress(progressPos, status.total);
      } else {
        setProgress(1, 1);
      }
      setButtonsDisabled(false);
      clearError();
      const toastMessage = reason === 'stoppedByStopWord'
        ? '✓ Automation stopped by stop phrase'
        : reason === 'completedWithErrors'
          ? (lastFailureError ? `Finished with failures. Last error: ${lastFailureError}` : 'Finished with some failed prompts')
          : '✓ Automation complete!';
      const toastKind = reason === 'completedWithErrors' ? 'info' : 'success';
      showToast(toastMessage, toastKind);
      stopCountdownTimer();
      updateControlButtons({ running: false, paused: false });
    } else if (message?.type === 'AUTOMATION_ERROR') {
      setStatus(`Error: ${message.error}`, 'error');
      setButtonsDisabled(false);
      showToast(`✗ Error: ${message.error}`, 'error', 5000);
      showError(
        `Automation Error: ${message.error}`,
        message.details || 'No additional details available',
        message.stack || 'No stack trace available'
      );
      stopCountdownTimer();
      // Refresh status after error to show proper state
      setTimeout(refreshStatus, 1000);
      updateControlButtons({ running: false, paused: false });
    }
  } catch (e) {
    console.error('[MessageListener] Error handling message:', e);
    showError('Failed to handle message', e.message, e.stack);
  }
});

// Use AbortController for auto-refresh instead of setInterval
let refreshAbortController = null;
let countdownAbortController = null;
let lastActivityTime = Date.now();

function startCountdownTimer() {
  if (countdownAbortController) return;
  countdownAbortController = new AbortController();
  const signal = countdownAbortController.signal;

  const doCountdown = async () => {
    if (signal.aborted) return;

    try {
      const res = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
      if (res?.ok && res.status?.running && !res.status?.paused) {
        const stableMs =
          res.status.stableCountdownMs ||
          res.status.options?.stableMs ||
          secToMs(Number(document.getElementById('stableMaxSec')?.value)) ||
          1200;
        const countdownEl = document.getElementById('stableCountdown');
        const countdownValue = document.getElementById('countdownValue');

        // Show countdown
        countdownEl.style.display = 'block';

        // Simulate countdown (updates every 100ms)
        const elapsed = Date.now() - lastActivityTime;
        const remaining = Math.max(0, stableMs - elapsed);
        const remainingSec = (remaining / 1000).toFixed(1);
        countdownValue.textContent = remainingSec;
      } else {
        // Hide countdown when not running
        const countdownEl = document.getElementById('stableCountdown');
        countdownEl.style.display = 'none';
      }
    } catch (e) {
      console.error('[Countdown] Error:', e);
    }

    if (!signal.aborted) {
      setTimeout(doCountdown, 100);
    }
  };
  doCountdown();
}

function stopCountdownTimer() {
  if (countdownAbortController) {
    countdownAbortController.abort();
    countdownAbortController = null;
  }
}

function startAutoRefresh() {
  if (refreshAbortController) return; // Already running
  refreshAbortController = new AbortController();
  const signal = refreshAbortController.signal;

  const doRefresh = async () => {
    if (signal.aborted) return;
    await refreshStatus();
    if (!signal.aborted) {
      setTimeout(doRefresh, 2000);
    }
  };
  doRefresh();
}

function stopAutoRefresh() {
  if (refreshAbortController) {
    refreshAbortController.abort();
    refreshAbortController = null;
  }
}

// Check for sample-export.json and prompt to load
async function checkForSampleExport() {
  try {
    const sampleUrl = chrome.runtime.getURL('sample-export.json');
    const response = await fetch(sampleUrl);
    if (!response.ok) return;

    const data = await response.json();
    if (!data.history || !Array.isArray(data.history) || data.history.length === 0) return;

    // Check if history is empty (no point prompting if user already has data)
    const res = await chrome.runtime.sendMessage({ type: 'GET_PROMPT_HISTORY' });
    if (res?.history && res.history.length > 0) return; // Already has history

    // Show confirmation toast
    if (confirm(`Found sample-export.json with ${data.history.length} saved prompt(s). Load it?`)) {
      await importSampleData(data);
    }
  } catch (e) {
    // File doesn't exist or can't be read - that's fine
    console.log('[SampleExport] No sample-export.json found or error:', e.message);
  }
}

async function importSampleData(importData) {
  try {
    const validItems = importData.history.filter(item => {
      if (!item || typeof item !== 'object') return false;
      if (!Array.isArray(item.prompts) || item.prompts.length === 0) return false;
      return true;
    });

    if (validItems.length === 0) {
      showToast('No valid items in sample file', 'error');
      return;
    }

    const itemsWithTimestamp = validItems.map(item => ({
      ...item,
      savedAt: item.savedAt || Date.now()
    }));

    await chrome.storage.local.set({ aiTaskSequencerHistory: itemsWithTimestamp.slice(0, 50) });
    await loadHistoryIntoUI();
    showToast(`✓ Loaded ${validItems.length} item(s) from sample`, 'success');
  } catch (e) {
    console.error('[ImportSample] Error:', e);
    showToast('Failed to load sample', 'error');

  }
}

